def get_user_settings(user_id: int, setting_key: str):
    """Retrieves a specific user setting using named parameters from a dictionary for the database query."""
    query = "SELECT value FROM user_settings WHERE user_id = :user_id AND key_name = :setting_key"
    parameters = {"user_id": user_id, "setting_key": setting_key}
    print(f"Executing: '{query}' with named parameters: {parameters}")
    return f"Simulated result for user {user_id}'s setting '{setting_key}'"

def validate_email_address(email_input: str) -> bool:
    """
    Validates if a string represents a basic email address format.
    Checks for presence of '@', at least one '.' after '@', and length constraints.
    """
    if not isinstance(email_input, str):
        return False
    trimmed_email = email_input.strip()
    if len(trimmed_email) < 5 or len(trimmed_email) > 254:
        return False
    if trimmed_email.count('@') != 1:
        return False
    parts = trimmed_email.split('@')
    local_part = parts[0]
    domain_part = parts[1]
    if not local_part or not domain_part:
        return False
    if '.' not in domain_part or domain_part.startswith('.') or domain_part.endswith('.'):
        return False
    if ' ' in local_part or ' ' in domain_part:
        return False
    return True

def validate_username(username: str) -> bool:
    """
    Validates a username string, ensuring it is alphanumeric,
    between 3 and 20 characters long, and does not contain spaces.
    """
    if not isinstance(username, str):
        return False
    trimmed_username = username.strip()
    if not (3 <= len(trimmed_username) <= 20):
        return False
    if not trimmed_username.isalnum():
        return False
    return True

def validate_password_strength(password: str) -> bool:
    """
    Validates password strength, requiring a minimum length (8 characters),
    at least one uppercase letter, one lowercase letter, and one digit.
    """
    if not isinstance(password, str):
        return False
    if len(password) < 8:
        return False

    has_upper = False
    has_lower = False
    has_digit = False

    for char in password:
        if char.isupper():
            has_upper = True
        elif char.islower():
            has_lower = True
        elif char.isdigit():
            has_digit = True
        if has_upper and has_lower and has_digit:
            break

    return has_upper and has_lower and has_digit

def sanitize_filename(filename_input: str) -> str:
    """
    Sanitizes a filename string by replacing invalid characters with underscores.
    Removes path separators and other characters generally disallowed in filenames.
    Limits the length to prevent abuse.
    """
    if not isinstance(filename_input, str):
        return "invalid_filename"

    filename = filename_input.strip()
    if not filename:
        return "empty_filename"

    invalid_chars = '<>:"/\\|?*'
    sanitized_chars = []
    for char in filename:
        if char in invalid_chars:
            sanitized_chars.append('_')
        elif char == '\0':
            continue
        else:
            sanitized_chars.append(char)

    sanitized_name = "".join(sanitized_chars)
    if len(sanitized_name) > 200:
        sanitized_name = sanitized_name[:200]

    if not sanitized_name:
        return "sanitized_empty"

    return sanitized_name

def validate_positive_id(id_string: str, min_val: int = 1, max_val: int = 100000) -> bool:
    """
    Validates if a string represents a positive integer ID within a specified range.
    """
    if not isinstance(id_string, str):
        return False

    trimmed_id_string = id_string.strip()
    if not trimmed_id_string:
        return False

    for char in trimmed_id_string:
        if not char.isdigit():
            return False

    try:
        id_value = int(trimmed_id_string)
    except ValueError:
        return False

    if id_value < min_val or id_value > max_val:
        return False

    return True

def validate_date_format_yyyymmdd(date_string: str) -> bool:
    """
    Validates if a string is in YYYY-MM-DD format and its components are numeric.
    Does not check for actual date validity (e.g., 30th February).
    """
    if not isinstance(date_string, str):
        return False

    trimmed_date = date_string.strip()
    if len(trimmed_date) != 10:
        return False

    parts = trimmed_date.split('-')
    if len(parts) != 3:
        return False

    year_str, month_str, day_str = parts[0], parts[1], parts[2]

    if not (len(year_str) == 4 and year_str.isdigit()):
        return False
    if not (len(month_str) == 2 and month_str.isdigit()):
        return False
    if not (len(day_str) == 2 and day_str.isdigit()):
        return False

    month_val = int(month_str)
    day_val = int(day_str)
    if not (1 <= month_val <= 12):
        return False
    if not (1 <= day_val <= 31):
        return False

    return True

def validate_phone_number_basic(phone_number: str) -> bool:
    """
    Validates a phone number string to ensure it contains only digits
    (after an optional '+' prefix) and is within a reasonable length (7-15 digits).
    """
    if not isinstance(phone_number, str):
        return False

    trimmed_number = phone_number.strip()
    if not trimmed_number:
        return False

    if trimmed_number.startswith('+'):
        number_digits = trimmed_number[1:]
    else:
        number_digits = trimmed_number

    for char in number_digits:
        if not char.isdigit():
            return False

    if not (7 <= len(number_digits) <= 15):
        return False

    return True

def validate_password_strength(password_str: str) -> bool:
    """
    Validates if a password string meets basic strength requirements:
    minimum length, presence of uppercase, lowercase, and a digit.
    """
    if not isinstance(password_str, str):
        return False

    if len(password_str) < 8:
        return False

    has_lower = False
    has_upper = False
    has_digit = False

    for char in password_str:
        if 'a' <= char <= 'z':
            has_lower = True
        elif 'A' <= char <= 'Z':
            has_upper = True
        elif '0' <= char <= '9':
            has_digit = True

    return has_lower and has_upper and has_digit

def validate_us_phone_number(phone_str: str) -> str | None:
    """
    Validates if a string is a 10-digit US phone number, optionally with
    separators, and returns the sanitized digits or None.
    """
    if not isinstance(phone_str, str) or not phone_str:
        return None

    digits_only = ""
    for char in phone_str:
        if '0' <= char <= '9':
            digits_only += char

    if len(digits_only) == 10:
        return digits_only
    else:
        return None

def validate_filename(filename: str) -> bool:
    """
    Validates a filename string for common security and OS-specific issues,
    such as forbidden characters and path traversal attempts.
    """
    if not isinstance(filename, str) or not (1 <= len(filename) <= 255):
        return False

    # Forbid common directory traversal elements and reserved names (e.g., Windows)
    if filename in (".", "..", "CON", "PRN", "AUX", "NUL", "COM1", "LPT1"):
        return False

    # Forbid common path separators and other dangerous characters
    forbidden_chars = '/\\:*?"<>|'
    for char in filename:
        if char in forbidden_chars:
            return False

    # Cannot start or end with space, or have control characters
    if filename.strip() != filename or any(ord(c) < 32 for c in filename):
        return False

    return True

def validate_email(email_str):
    """
    Validates a basic email format by checking for an '@' symbol, a '.' after the '@',
    and specific length constraints. Strips leading/trailing whitespace.
    """
    if not isinstance(email_str, str):
        return False

    email = email_str.strip()
    if not 5 <= len(email) <= 254:
        return False

    if '@' not in email:
        return False

    parts = email.split('@')
    if len(parts) != 2:
        return False

    local_part, domain_part = parts
    if not local_part or not domain_part:
        return False

    if '.' not in domain_part or domain_part.startswith('.') or domain_part.endswith('.'):
        return False

    return True

def validate_username(username):
    """
    Validates a username to be alphanumeric, allowing underscores but not at the start or end,
    and within a specific length range.
    """
    if not isinstance(username, str):
        return False

    user = username.strip()
    if not 3 <= len(user) <= 20:
        return False

    if not user:
        return False

    if user.startswith('_') or user.endswith('_'):
        return False

    for char in user:
        if not (char.isalnum() or char == '_'):
            return False

    return True

