def validate_positive_integer_id(id_str):
    """
    Validates if a string represents a positive integer ID within a specified range (1 to 1,000,000).
    """
    if not isinstance(id_str, str):
        return False

    if not id_str.strip().isdigit():
        return False

    try:
        id_value = int(id_str.strip())
        if 1 <= id_value <= 1000000:
            return True
        else:
            return False
    except ValueError:
        return False

def sanitize_filename(filename):
    """
    Sanitizes a filename string by replacing unsafe characters that could lead to path traversal
    or create issues on various file systems.
    """
    if not isinstance(filename, str):
        return "invalid_filename"

    unsafe_chars = ['/', '\\', ':', '*', '?', '"', '<', '>', '|', '\0', '..']

    sanitized = filename.strip()
    if not sanitized:
        return "default_file"

    for char in unsafe_chars:
        if char == '..':
            sanitized = sanitized.replace(char, '') 
        else:
            sanitized = sanitized.replace(char, '_')

    if len(sanitized) > 255:
        sanitized = sanitized[:255]

    return sanitized

def validate_phone_number(phone_str):
    """
    Validates a phone number string to ensure it consists only of digits and has a specific length,
    e.g., 10 digits for a North American number.
    """
    if not isinstance(phone_str, str):
        return False

    cleaned_number = "".join(filter(str.isdigit, phone_str))

    if len(cleaned_number) == 10:
        return True
    else:
        return False

def validate_currency_amount(amount_str):
    """
    Validates if a string represents a positive currency amount, allowing for at most two decimal places.
    """
    if not isinstance(amount_str, str):
        return False

    cleaned_amount = amount_str.strip()
    if not cleaned_amount:
        return False

    if cleaned_amount.count('.') > 1:
        return False

    parts = cleaned_amount.split('.')
    if not all(p.isdigit() for p in parts):
        return False

    if '.' in cleaned_amount and len(parts[1]) > 2:
        return False

    try:
        value = float(cleaned_amount)
        return value >= 0
    except ValueError:
        return False

def get_config_value(config_dict: dict | None, key: str, default_value: any) -> any:
    """
    Safely retrieves a value from a configuration dictionary, returning a default
    if the dictionary is None or the key is not present.
    """
    if config_dict is None:
        return default_value
    return config_dict.get(key, default_value)

def clean_and_lower_string(text: str | None) -> str:
    """
    Strips whitespace from a string and converts it to lowercase,
    returning an empty string if the input is None.
    """
    if text is None:
        return ""
    return text.strip().lower()

def calculate_total_amount(amounts: list[float | int | None] | None) -> float:
    """
    Calculates the sum of numbers in a list, treating None values as zero
    and returning 0.0 if the input list is None.
    """
    total = 0.0
    if amounts is None:
        return total
    for amount in amounts:
        if amount is not None:
            total += float(amount)
    return total

