def get_user_email(user_obj: User | None, default_email: str = "no_email@example.com") -> str:
    """
    Safely retrieves the email attribute from a User object, returning a default
    if the object is None or its email attribute is None.
    """
    if user_obj is None or user_obj.email is None:
        return default_email
