def calculate_product_price(base_price: float | int | None, quantity: int | None) -> float:
    """
    Calculates the total product price by multiplying base price and quantity,
    returning 0.0 if either input is None.
    """
    if base_price is None or quantity is None:
        return 0.0
    return float(base_price) * float(quantity)

def get_nested_dict_value(data: dict | None, keys: list[str], default: any = None) -> any:
    """
    Safely retrieves a value from a nested dictionary given a list of keys,
    returning a default value if any intermediate dictionary or the final value is None.
    """
    if data is None:
        return default

    current_level = data
    for key in keys:
        if not isinstance(current_level, dict) or current_level.get(key) is None:
            return default
        current_level = current_level.get(key)
    return current_level

class Item:
    def __init__(self, item_id: str, quantity: int | None):
        self.item_id = item_id
        self.quantity = quantity

def extract_valid_quantities(items: list[Item | None] | None) -> list[int]:
    """
    Extracts valid quantities from a list of Item objects,
    ignoring None items or items with None quantities.
    Returns an empty list if input is None.
    """
    quantities = []
    if items is None:
        return quantities
    for item in items:
        if item is not None and item.quantity is not None:
            quantities.append(item.quantity)
    return quantities

def parse_optional_int(s_value: str | None, default_int: int = 0) -> int:
    """
    Parses an optional string value to an integer, returning a default
    if the string is None or cannot be converted to an integer.
    """
    if s_value is None:
        return default_int
    try:
        return int(s_value)
    except (ValueError, TypeError):
        return default_int

def get_first_element(data_list):
    """
    Returns the first element of a list if the list is not None and not empty,
    otherwise returns None.
    """
    if data_list is None:
        return None
    if not isinstance(data_list, list):
        return None
    if not data_list:
        return None
    return data_list[0]

def get_config_value(config_dict, key, default_value=None):
    """
    Retrieves a value from a configuration dictionary for a given key,
    returning a default value if the dictionary is None or the key is not found.
    """
    if config_dict is None:
        return default_value
    if not isinstance(config_dict, dict):
        return default_value
    return config_dict.get(key, default_value)

class Product:
