def calculate_discounted_price(original_price, discount_percentage):
    """
    Calculates the discounted price given an original price and a discount percentage.
    Returns None if either input is None, not a valid number (int/float), or outside valid ranges.
    """
    if original_price is None or discount_percentage is None:
        return None

    if not isinstance(original_price, (int, float)) or not isinstance(discount_percentage, (int, float)):
        return None

    if original_price < 0:
        return None

    if not (0 <= discount_percentage <= 100):
        return None

    discount_factor = (100 - discount_percentage) / 100
    return original_price * discount_factor

