def extract_contact_email(user_obj):
    """
    Extracts the contact email from a nested User object structure.
    Returns None if any part of the path (user, profile, contact, email) is None.
    """
    if user_obj is None:
        return None

    profile = getattr(user_obj, 'profile', None)
    if profile is None:
        return None

    contact = getattr(profile, 'contact', None)
    if contact is None:
        return None

    email = getattr(contact, 'email', None)
    return email

def get_status_message(status_code, error_message=None):
    """
    Generates a status message based on a status code and an optional error message.
    Returns different messages depending on the presence of an error or the status code.
    """
    if error_message is not None and str(error_message).strip():
        return f"Error: {error_message}"

    if status_code is None:
        return "Status unknown."

    if status_code == 200:
        return "Operation successful."
    elif status_code >= 400 and status_code < 500:
        return "Client error occurred."
    elif status_code >= 500:
        return "Server error occurred."
    else:
        return f"Status: {status_code}"

def log_event(event_type, message, details=None):
    """
    Logs an event with its type, message, and optional details.
    Handles 'details' being None by representing it as 'N/A' in the log output.
    """
    if details is None:
        detail_str = "N/A"
    else:
        detail_str = str(details)

    return f"Event Type: {event_type}, Message: {message}, Details: {detail_str}"

def parse_coordinates(coordinate_tuple):
    """
    Parses a tuple representing (x, y) coordinates.
    Returns (None, None) if the input is None, not a tuple, does not have exactly two elements,
    or contains non-numeric elements.
    """
    if coordinate_tuple is None:
        return (None, None)

    if not isinstance(coordinate_tuple, tuple):
        return (None, None)

    if len(coordinate_tuple) != 2:
        return (None, None)

    x, y = coordinate_tuple

    if not isinstance(x, (int, float)) or not isinstance(y, (int, float)):
        return (None, None)

    return (x, y)

def safe_divide(numerator: float, denominator: float) -> float | str:
    """
    Performs division safely, returning an error message if the denominator is zero or inputs are not numeric.
    """
    if not isinstance(numerator, (int, float)) or not isinstance(denominator, (int, float)):
        return "Error: Both numerator and denominator must be numbers."
    if denominator == 0:
        return "Error: Cannot divide by zero."
    return numerator / denominator

def calculate_percentage_change(old_value: float, new_value: float) -> float | str:
    """
    Calculates the percentage change between an old value and a new value,
    handling cases where the old value is zero or inputs are not numeric.
    """
    if not isinstance(old_value, (int, float)) or not isinstance(new_value, (int, float)):
        return "Error: Both values must be numbers."
    if old_value == 0:
        if new_value == 0:
            return 0.0  # No change if both are zero
        return "Error: Cannot calculate percentage change from zero old value unless new value is also zero."
    return ((new_value - old_value) / old_value) * 100

def calculate_list_average(numbers: list[float]) -> float | str:
    """
    Calculates the average of a list of numbers, returning an error if the list is empty
    or contains non-numeric values.
    """
    if not isinstance(numbers, list):
        return "Error: Input must be a list."
    if not numbers:
        return "Error: Cannot calculate average of an empty list."

    total = 0.0
    for num in numbers:
        if not isinstance(num, (int, float)):
            return "Error: All elements in the list must be numbers."
        total += num
    return total / len(numbers)

def calculate_future_value(principal: float, annual_rate: float, years: int, compounds_per_year: int) -> float | str:
    """
    Calculates the future value of an investment with compound interest,
    validating inputs to ensure they are positive and sensible.
    """
    if not all(isinstance(arg, (int, float)) for arg in [principal, annual_rate]) or not all(isinstance(arg, int) for arg in [years, compounds_per_year]):
        return "Error: Principal and annual rate must be numbers, years and compounds_per_year integers."
    if principal < 0:
        return "Error: Principal cannot be negative."
    if annual_rate < -1.0:
        return "Error: Annual rate cannot be less than -1.0 (or -100%)."
    if years < 0:
        return "Error: Years cannot be negative."
    if compounds_per_year <= 0:
        return "Error: Compounds per year must be a positive integer."

    rate_per_period = annual_rate / compounds_per_year
    num_periods = years * compounds_per_year

    future_value = principal * (1 + rate_per_period) ** num_periods
    return round(future_value, 2)

def normalize_vector(vector: list[float]) -> list[float] | str:
    """
    Normalizes a vector to its L2-norm, returning an error if the vector is empty,
    contains non-numeric values, or if its magnitude is zero.
    """
    if not isinstance(vector, list):
        return "Error: Input must be a list."
    if not vector:
        return "Error: Cannot normalize an empty vector."

    magnitude_sq = 0.0
    for x in vector:
        if not isinstance(x, (int, float)):
            return "Error: All elements in the vector must be numbers."
        magnitude_sq += x * x

    magnitude = magnitude_sq ** 0.5

    if magnitude == 0:
        return "Error: Cannot normalize a zero vector (magnitude is zero).
    "

    normalized_vector = [x / magnitude for x in vector]
    return normalized_vector

def calculate_simple_moving_average(data: list[float], window_size: int) -> list[float] | str:
    """
    Calculates the simple moving average for a list of numeric data over a specified window size,
    handling invalid window sizes or non-numeric data.
    """
    if not isinstance(data, list) or not isinstance(window_size, int):
        return "Error: Data must be a list and window_size an integer."
    if window_size <= 0:
        return "Error: Window size must be a positive integer."
    if window_size > len(data):
        return "Error: Window size cannot be greater than the number of data points."

    moving_averages = []
    for i in range(len(data) - window_size + 1):
        window = data[i:i + window_size]
        current_sum = 0.0
        for item in window:
            if not isinstance(item, (int, float)):
                return "Error: All data points must be numbers."
            current_sum += item
        moving_averages.append(current_sum / window_size)

    return moving_averages

def sum_geometric_progression(first_term: float, common_ratio: float, num_terms: int) -> float | str:
    """
    Calculates the sum of a geometric progression, handling cases where the common ratio is 1
    or inputs are invalid.
    """
    if not all(isinstance(arg, (int, float)) for arg in [first_term, common_ratio]) or not isinstance(num_terms, int):
        return "Error: First term and common ratio must be numbers, number of terms an integer."
    if num_terms < 0:
        return "Error: Number of terms cannot be negative."
    if num_terms == 0:
        return 0.0

    if common_ratio == 1:
        return first_term * num_terms
    else:
        return first_term * (1 - common_ratio**num_terms) / (1 - common_ratio)

def calculate_percentage_change(old_value: float, new_value: float) -> float:
    """
    Calculates the percentage change from an old value to a new value.
    Handles zero old_value by returning 0.0 if new_value is also zero,
    otherwise returns float('inf') for positive change or float('-inf') for negative change.
    """
    if old_value == 0.0:
        if new_value == 0.0:
            return 0.0
        else:
            return float('inf') if new_value > 0 else float('-inf')

    return ((new_value - old_value) / old_value) * 100.0

def calculate_final_cost(item_prices: list[float], discount_percentage: float) -> float:
    """
    Calculates the total cost of multiple items after applying a percentage discount.
    """
    if not isinstance(item_prices, list) or not all(isinstance(p, (int, float)) for p in item_prices):
        raise TypeError("item_prices must be a list of numbers.")
    if not isinstance(discount_percentage, (int, float)):
        raise TypeError("discount_percentage must be a number.")
    if not (0 <= discount_percentage <= 100):
        raise ValueError("Discount percentage must be between 0 and 100.")

    total_gross_cost = sum(item_prices)
    discount_factor = (100 - discount_percentage) / 100.0
    final_cost = total_gross_cost * discount_factor
    return max(0.0, final_cost)

def calculate_compound_future_value(principal: float, annual_rate: float, years: int, compounds_per_year: int) -> float:
    """
    Calculates the future value of an investment with compound interest.
    """
    if not all(isinstance(arg, (int, float)) for arg in [principal, annual_rate]):
        raise TypeError("Principal and annual rate must be numbers.")
    if not all(isinstance(arg, int) for arg in [years, compounds_per_year]):
        raise TypeError("Years and compounds_per_year must be integers.")
    if principal < 0:
        raise ValueError("Principal cannot be negative.")
    if years < 0:
        raise ValueError("Years cannot be negative.")
    if compounds_per_year <= 0:
        raise ValueError("Compounds per year must be a positive integer.")

    rate_per_period = annual_rate / compounds_per_year
    total_periods = years * compounds_per_year
    future_value = principal * (1 + rate_per_period) ** total_periods
    return future_value

def calculate_net_income(gross_income: float, tax_rate_percent: float) -> float:
    """
    Calculates net income by subtracting a percentage tax from gross income.
    """
    if not all(isinstance(arg, (int, float)) for arg in [gross_income, tax_rate_percent]):
        raise TypeError("Gross income and tax rate must be numbers.")
    if gross_income < 0:
        raise ValueError("Gross income cannot be negative.")
    if not (0 <= tax_rate_percent <= 100):
        raise ValueError("Tax rate must be between 0 and 100 percent.")

    tax_amount = gross_income * (tax_rate_percent / 100.0)
    net_income = gross_income - tax_amount
    return net_income

def scale_value(value: float, original_min: float, original_max: float, target_min: float, target_max: float) -> float:
    """
    Scales a value from an original range to a new target range.
    """
    if not all(isinstance(arg, (int, float)) for arg in [value, original_min, original_max, target_min, target_max]):
        raise TypeError("All input arguments must be numbers.")
    if original_min > original_max:
        raise ValueError("Original minimum cannot be greater than original maximum.")
    if target_min > target_max:
        raise ValueError("Target minimum cannot be greater than target maximum.")

    original_range_span = original_max - original_min
    if original_range_span == 0:
        if value == original_min:
            return target_min
        else:
            raise ValueError("Value is outside the zero-span original range.")

    scaled_value = ((value - original_min) / original_range_span) * (target_max - target_min) + target_min
    return scaled_value

