def create_product(product_data):
    """
    Creates a new product, validating required fields and types from a JSON-like dict.
    """
    if not isinstance(product_data, dict):
        return {"error": "Request body must be a JSON object.", "status": 400}

    required_fields = ["name", "price"]
    for field in required_fields:
        if field not in product_data:
            return {"error": f"Missing field: '{field}'.", "status": 400}

    # Basic type and value validation
    if not isinstance(product_data["name"], str) or not product_data["name"].strip():
        return {"error": "Name must be a non-empty string.", "status": 400}
    if not isinstance(product_data["price"], (int, float)) or product_data["price"] <= 0:
        return {"error": "Price must be a positive number.", "status": 400}

    # Optional field
    description = product_data.get("description", "").strip()

    # Simulate saving to DB and returning new product info
    new_product_id = 1001 # Generated by DB
    return {
        "data": {
            "id": new_product_id,
            "name": product_data["name"].strip(),
            "price": product_data["price"],
            "description": description
        },
        "status": 201
    }

def search_items(query_param):
    """
    Searches for items using a query string, sanitizing it to prevent basic injection.
    """
    if not isinstance(query_param, str) or not query_param.strip():
        return {"error": "Search query cannot be empty.", "status": 400}

    # Simulate a very basic 'SQL-like' escape to protect against simple injection if used in a raw string query
    # In a real app, prepared statements are used, but this demonstrates input sanitization.
    sanitized_query = query_param.strip().replace("'", "''").replace("%", "\\%").replace("_", "\\_")

    # Simulate a search operation with sanitized query
    matching_items = []
    if "example" in sanitized_query.lower():
        matching_items.append({"id": 201, "name": "Example Item A"})
    if "test" in sanitized_query.lower():
        matching_items.append({"id": 202, "name": "Test Product B"})

    if matching_items:
        return {"data": matching_items, "count": len(matching_items), "status": 200}
    else:
        return {"data": [], "count": 0, "message": "No items found.", "status": 200}

def update_order_status(order_id_str, update_data, current_user_id):
    """
    Updates an order's status, validating inputs and simulating an authorization check.
    """
    try:
