        if order_id <= 0:
            return {"error": "Invalid order ID.", "status": 400}
    except ValueError:
        return {"error": "Order ID must be an integer.", "status": 400}

    if not isinstance(update_data, dict) or "status" not in update_data:
        return {"error": "Request body must specify 'status'.", "status": 400}

    new_status = update_data["status"]
    if not isinstance(new_status, str) or new_status not in ["pending", "shipped", "delivered", "cancelled"]:
        return {"error": "Invalid status value.", "status": 400}

    # Simulate authorization: Only user 101 can update order 501
    if order_id == 501 and current_user_id != 101:
        return {"error": "Unauthorized to update this order.", "status": 403}

    # Simulate database update
    return {"message": f"Order {order_id} status updated to {new_status}.", "status": 200}

