def get_application_configuration(is_admin_request):
    """
    Retrieves application configuration, hiding sensitive details from non-admin users.
    """
    full_config = {
        "app_name": "SecureApp",
        "version": "1.0.0",
        "database_url": "mysql://user:password@host/db", # Sensitive
        "api_key": "supersecretkey123", # Sensitive
        "log_level": "INFO",
        "feature_flags": {"new_ui": True, "beta_mode": False}
    }

    if is_admin_request:
        return {"data": full_config, "status": 200}
    else:
        # Filter out sensitive information for non-admin users
        public_config = {
            k: v for k, v in full_config.items()
            if k not in ["database_url", "api_key"]
        }
        return {"data": public_config, "status": 200}

def handle_login(credentials):
    """
    Handles a login attempt, validating username and password format.
    """
    if not isinstance(credentials, dict):
        return {"error": "Request body must be a JSON object.", "status": 400}

    username = credentials.get("username")
    password = credentials.get("password")

    if not isinstance(username, str) or not username.strip():
        return {"error": "Username is required.", "status": 400}
    if not isinstance(password, str) or not password.strip():
        return {"error": "Password is required.", "status": 400}

    # Basic length check for security (e.g., brute force protection)
    if len(username) < 3 or len(username) > 50:
        return {"error": "Username length invalid.", "status": 400}
    if len(password) < 8 or len(password) > 100:
        return {"error": "Password length invalid.", "status": 400}

    # In a real app, username/password would be hashed and compared securely.
    # Here we just acknowledge valid format.
    clean_username = username.strip() # Sanitize before further use (e.g., logging)

    # Simulate success (not actual authentication)
    return {"message": f"Login attempt for user '{clean_username}' processed.", "status": 200}

def _html_escape(text):
    return text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;').replace("'", '&#x27;')

def get_all_messages(user_id):
    """
    Retrieves a list of messages for a user, ensuring message content is HTML-escaped.
    """
    # Simulate fetching messages from a database
    raw_messages = [
        {"id": 1, "sender": "Admin", "content": "Welcome to our site! Click <a href='/help'>here</a>."},
        {"id": 2, "sender": "UserX", "content": "Hello & goodbye <script>alert('xss');</script>"},
        {"id": 3, "sender": "System", "content": "Your payment is due."}
    ]

    escaped_messages = []
    for msg in raw_messages:
        # Ensure that content is HTML-escaped for safe display in a web browser
        escaped_messages.append({
            "id": msg["id"],
            "sender": _html_escape(msg["sender"]),
            "content": _html_escape(msg["content"])
        })

    return {"data": escaped_messages, "count": len(escaped_messages), "status": 200}

def _html_escape(text):
    return text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;').replace("'", '&#x27;')

def post_new_comment(comment_data, author_id):
    """
    Receives a new comment, sanitizes its content for HTML safety, and 'stores' it.
    """
    if not isinstance(comment_data, dict) or "content" not in comment_data:
        return {"error": "Comment content is required.", "status": 400}

    raw_content = comment_data["content"]
    if not isinstance(raw_content, str) or not raw_content.strip():
        return {"error": "Comment content cannot be empty.", "status": 400}

    # Sanitize content before processing/storing to prevent XSS on display
    sanitized_content = _html_escape(raw_content.strip())

    # Simulate saving to database and returning the clean comment
    new_comment_id = 901
    return {
        "data": {
            "id": new_comment_id,
            "author_id": author_id,
            "content": sanitized_content,
            "timestamp": "2023-10-27T10:00:00Z" # Simulated
        },
        "message": "Comment posted successfully.",
        "status": 201
    }
